from __future__ import annotations

from pathlib import Path

path = Path("scripts/run_trading_strategy_liquidity_sweep.py")
text = path.read_text(encoding="utf-8")
old_import = "from app.trading.providers.errors import ProviderRateLimitedError"
new_import = "from app.trading.providers.errors import ProviderContractError, ProviderDataUnavailableError, ProviderRateLimitedError"
if text.count(old_import) != 1:
    raise RuntimeError("unexpected provider-error import shape")
text = text.replace(old_import, new_import)
old = '''            active_reconstructor, active_regular_runtime = ensure_provider_clients()\n            print(f"Cache miss for {session_date}; reconstructing once for {len(thresholds)} variants")\n            reconstruction = _with_rate_limit_retry(\n                f"reconstruct {session_date}",\n                lambda session_date=session_date: active_reconstructor(\n                    session_date=session_date,\n                    scan_time=time(9, 20),\n                    config=reconstruction_strategy.config,\n                    assumed_spread_bps=assumed_spread_bps,\n                    max_age_days=args.reconstruction_max_age_days,\n                ),\n            )\n            universe = reconstruction.snapshot\n            if universe is None:\n                if reconstruction.fidelity == "reconstructed_current_listings_iex":\n                    no_candidate_detail = reconstruction.detail or "Historical scan found no candidates."\n                    if no_candidate_path is not None:\n                        no_candidate_path.write_text(\n                            json.dumps(\n                                {\n                                    "cache_version": _DATASET_CACHE_VERSION,\n                                    "session_date": session_date.isoformat(),\n                                    "fidelity": reconstruction.fidelity,\n                                    "detail": no_candidate_detail,\n                                    "warnings": list(reconstruction.warnings),\n                                },\n                                indent=2,\n                                sort_keys=True,\n                            )\n                            + "\\n",\n                            encoding="utf-8",\n                        )\n                else:\n                    unavailable_sessions.append(\n                        {\n                            "session_date": session_date.isoformat(),\n                            "fidelity": reconstruction.fidelity,\n                            "detail": reconstruction.detail,\n                        }\n                    )\n                    continue\n            else:\n                bars_by_instrument = _with_rate_limit_retry(\n                    f"regular bars {session_date}",\n                    lambda universe=universe, session_date=session_date: alpaca_historical_session_bars(\n                        universe.candidates,\n                        session_date,\n                        runtime=active_regular_runtime,\n                    ),\n                )\n                dataset = freeze_backtest_session(\n                    session_date=session_date,\n                    universe=universe,\n                    bars_by_instrument=bars_by_instrument,\n                )\n                if dataset_path is not None:\n                    _write_cached_dataset(dataset_path, dataset)\n                    print(f"Cached frozen dataset for {session_date}: {dataset.dataset_fingerprint}")\n'''
new = '''            active_reconstructor, active_regular_runtime = ensure_provider_clients()\n            print(f"Cache miss for {session_date}; reconstructing once for {len(thresholds)} variants")\n            try:\n                reconstruction = _with_rate_limit_retry(\n                    f"reconstruct {session_date}",\n                    lambda session_date=session_date: active_reconstructor(\n                        session_date=session_date,\n                        scan_time=time(9, 20),\n                        config=reconstruction_strategy.config,\n                        assumed_spread_bps=assumed_spread_bps,\n                        max_age_days=args.reconstruction_max_age_days,\n                    ),\n                )\n                universe = reconstruction.snapshot\n                if universe is None:\n                    if reconstruction.fidelity == "reconstructed_current_listings_iex":\n                        no_candidate_detail = reconstruction.detail or "Historical scan found no candidates."\n                        if no_candidate_path is not None:\n                            no_candidate_path.write_text(\n                                json.dumps(\n                                    {\n                                        "cache_version": _DATASET_CACHE_VERSION,\n                                        "session_date": session_date.isoformat(),\n                                        "fidelity": reconstruction.fidelity,\n                                        "detail": no_candidate_detail,\n                                        "warnings": list(reconstruction.warnings),\n                                    },\n                                    indent=2,\n                                    sort_keys=True,\n                                )\n                                + "\\n",\n                                encoding="utf-8",\n                            )\n                    else:\n                        unavailable_sessions.append(\n                            {\n                                "session_date": session_date.isoformat(),\n                                "fidelity": reconstruction.fidelity,\n                                "detail": reconstruction.detail,\n                            }\n                        )\n                        continue\n                else:\n                    bars_by_instrument = _with_rate_limit_retry(\n                        f"regular bars {session_date}",\n                        lambda universe=universe, session_date=session_date: alpaca_historical_session_bars(\n                            universe.candidates,\n                            session_date,\n                            runtime=active_regular_runtime,\n                        ),\n                    )\n                    dataset = freeze_backtest_session(\n                        session_date=session_date,\n                        universe=universe,\n                        bars_by_instrument=bars_by_instrument,\n                    )\n                    if dataset_path is not None:\n                        _write_cached_dataset(dataset_path, dataset)\n                        print(f"Cached frozen dataset for {session_date}: {dataset.dataset_fingerprint}")\n            except (ProviderContractError, ProviderDataUnavailableError, OSError) as exc:\n                unavailable_sessions.append(\n                    {\n                        "session_date": session_date.isoformat(),\n                        "fidelity": "provider_data_unavailable",\n                        "detail": f"{type(exc).__name__}: {exc}",\n                    }\n                )\n                print(f"{session_date}: provider data unavailable; preserving completed cache and continuing: {exc}")\n                continue\n'''
if text.count(old) != 1:
    raise RuntimeError(f"unexpected cache-miss block shape: {text.count(old)} matches")
path.write_text(text.replace(old, new), encoding="utf-8")

# The exploration must never turn provider holes into flat/no-trade sessions, but
# requiring literally 100% coverage makes a large historical block brittle. Keep
# missing dates explicit and require a strong predeclared coverage floor instead.
exploration_path = Path("scripts/run_trading_strategy_v2_extended_exploration.py")
exploration = exploration_path.read_text(encoding="utf-8")
strict = '''    if dev_meta["missing_sessions"] or val_meta["missing_sessions"]:\n        # Missing provider sessions are never silently turned into no-trade days.\n        print(json.dumps({"development": dev_meta, "validation": val_meta}, indent=2))\n        raise SystemExit(2)\n'''
coverage = '''    def require_coverage(label: str, meta: dict[str, object], *, absolute_floor: int) -> None:\n        requested = int(meta["requested_sessions"])\n        covered = int(meta["covered_sessions"])\n        required = max(absolute_floor, math.ceil(requested * 0.80))\n        if covered < required:\n            print(json.dumps({label: meta, "required_covered_sessions": required}, indent=2))\n            raise SystemExit(2)\n\n    # Missing provider sessions stay explicit/excluded. A block is usable only if\n    # at least 80% is covered (and at least 20 dev / 10 validation sessions).\n    require_coverage("development", dev_meta, absolute_floor=20)\n    require_coverage("validation", val_meta, absolute_floor=10)\n'''
if exploration.count(strict) != 1:
    raise RuntimeError(f"unexpected exploration coverage block: {exploration.count(strict)} matches")
exploration_path.write_text(exploration.replace(strict, coverage), encoding="utf-8")

print("Applied per-session provider-hole resilience and explicit 80% historical coverage floors.")
